 outcome-<?=e($outcome)?>"><?php if($outcome==='gol'): ?><svg class="outcome-icon" viewBox="0 0 24 24" width="11" height="11" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="12" cy="12" r="9"/><path d="M12 7l3 2v3.5l-3 2-3-2V9z"/><path d="M12 3v4M15 9l3.5-1.5M15 12.5l3.5 1.5M12 14.5v4.5M9 12.5L5.5 14M9 9L5.5 7.5"/></svg><?php elseif($outcome==='assistência'): ?><svg class="outcome-icon" viewBox="0 0 24 24" width="11" height="11" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M4 17l4-1 6 3h5a2 2 0 0 0 2-2v-1l-3-4-5-1-4 2-5 3z"/><path d="M10 11l-2 3M13 12l-1 3"/></svg><?php endif ?><?=e($outcome)?></small></span></button><?php endforeach ?></form></article><?php endif ?>
<?php else: $s=Game::situation($g); ?><?php if($g['stage']==='pre_jogo' && $m): ?><article class="panel match compact-score pre-match-banner"><div class="match-time">PRÓXIMA PARTIDA · RODADA <?=e($m['round'])?></div><div class="score-row"><span class="score-team"><?php ClubBadge::render($m['home']); ?><span><?=e(ClubBadge::name($m['home']))?></span></span><strong>VS</strong><span class="score-team"><?php ClubBadge::render($m['away']); ?><span><?=e(ClubBadge::name($m['away']))?></span></span></div><?php $agg=Competition::aggregateContext($g,$m); if($agg) Presentation::renderAggregate($agg); ?><div class="live-player-stats"><span>👕 <b><?=e(ucfirst($m['lineup']??'titular'))?></b></span><span>⚡ Energia <b><?=e($g['states']['energia']??100)?>%</b></span><span>🎯 Ritmo <b><?=e($g['states']['ritmo_jogo']??50)?>%</b></span></div></article><?php endif ?><?php if($g['stage']==='fim_semana'): ?><article class="panel post-match"><p class="tag">APITO FINAL</p><h2><?=e($m['home'].' '.$m['hg'].' × '.$m['ag'].' '.$m['away'])?></h2><?php $agg=Competition::aggregateContext($g,$m); if($agg) Presentation::renderAggregate($agg); ?><?php $shootoutPending = $m && class_exists('PenaltyShootout') && PenaltyShootout::requiresShootout($g, $m); if($shootoutPending): ?><div class="shootout-start-card shootout-inline-cta"><div class="shootout-cta-header"><span class="tag shootout-tag">⚽ DECISÃO DA VAGA</span><h2>Disputa de Pênaltis</h2><p>O tempo regulamentar terminou empatado no agregado (<b><?=e($agg['home_aggregate'] ?? 0)?> × <?=e($agg['away_aggregate'] ?? 0)?></b>). A vaga será decidida agora na marca do pênalti!</p></div><?php if (function_exists('form')) form('/penaltis/iniciar', $g); else echo '<form method="post" action="/penaltis/iniciar">'; ?><button class="btn btn-primary btn-lg btn-shootout-start">Começar as cobranças de pênaltis →</button></form></div><?php endif ?><?php MatchExperience::render($m); ?></article><?php endif ?><?php if($g['stage']!=='fim_semana' || empty($shootoutPending)): ?><article class="panel<?= ($s['id']??0)>=2000?' narrative-scene':'' ?>"><p class="tag"><?=e(str_replace('_',' ',strtoupper($g['stage'])))?></p><h2><?=e($s['text'])?></h2><p>O que você faz?</p><?php form('/decisao/registrar',$g); foreach(Game::choices($g) as $i=>$o): ?><button class="choice" name="option" value="<?=e($i)?>"><b><?=e(chr(65+$i))?></b><span><?=e($o['text'])?></span></button><?php endforeach ?></form></article><?php endif ?>
<?php if($g['stage']==='fim_semana' && empty($shootoutPending)): ?><details class="panel season-recap"><summary>Ver resumo da partida e meus gols</summary><?php Presentation::matchStats($g,$m); Presentation::goalHistory($g); Presentation::radio($m); ?><a href="/classificacao">Resultados e tabela →</a></details><?php endif ?><?php endif ?><?php if(!in_array($g['stage'],['handicap','clube_inicio','partida','penaltis','fim_semana','resumo','oferta','competicao_resumo'],true)) Presentation::goalHistory($g); ?></section><aside class="career-extras"><a class="profile-entry panel" href="/conquistas">Sala de Conquistas →</a><a class="profile-entry panel" href="/carreira/trofeus">Sala de Troféus →</a><a class="profile-entry panel" href="/jogador"><span>MEU JOGADOR</span><strong>Habilidades e evolução ↗</strong><small>Condição física, desempenho e reputação</small></a><details class="panel"><summary>Temporadas anteriores</summary><?php foreach($g['history'] as $h): ?><p>Temporada <?=e($h['season'])?> · <?=e($h['club'])?> · <?=e($h['goals'])?> gols · nota <?=e($h['average'])?></p><?php endforeach ?><?php if(!$g['history']): ?><p>Seu primeiro capítulo está em construção.</p><?php endif ?></details><details class="panel"><summary>Minha carreira</summary><p><a href="/carreira/nova">Começar nova carreira</a> · <a href="/carreiras">Gerenciar carreiras</a></p><p><a href="/carreira/arquivadas">Retomar carreira arquivada</a></p></details></aside></div><?php endif ?><?php endif ?>
